import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.time.*;
import java.util.*;
import remframework.geometry.discovery.eligibility.TopologyEligibilityAnalyzer;
import remframework.geometry.discovery.experiment.*;
public final class ConfigurationStore {
    private final Path root;
    public ConfigurationStore(Path root){this.root=root;}
    public static ConfigurationStore defaults(){return new ConfigurationStore(Path.of("lattice/geometry-discovery/configuration-sets"));}
    public Path save(GenerationResult result)throws IOException{Path set=root.resolve(result.setId()),details=set.resolve("configurations");Files.createDirectories(details);Files.writeString(set.resolve("request.toml"),request(result.request()),StandardCharsets.UTF_8);StringBuilder csv=new StringBuilder("configurationId,N,K,edgeCount,symmetry,automorphismCount,status,geometryTestStatus,diagnosticSummary\n");for(Configuration c:result.configurations()){Files.writeString(details.resolve(c.id()+".toml"),configuration(c,result.request()),StandardCharsets.UTF_8);csv.append(c.id()).append(',').append(c.nodeCount()).append(',').append(c.exactDegree()).append(',').append(c.edges().size()).append(',').append(c.graphSymmetry()).append(',').append(c.automorphismGroupSize()).append(',').append(c.status().code()).append(",NOT_TESTED,").append(csv(c.status().summary())).append('\n');}Files.writeString(set.resolve("configurations.csv"),csv,StandardCharsets.UTF_8);Files.writeString(set.resolve("generation-summary.toml"),summary(result),StandardCharsets.UTF_8);return set;}
    public List<Configuration> reopen(Path set)throws IOException{List<Configuration> result=new ArrayList<>();Path directory=set.resolve("configurations");if(Files.notExists(directory))return result;try(var files=Files.list(directory)){for(Path file:files.filter(p->p.toString().endsWith(".toml")).sorted().toList())result.add(parse(file));}return result;}
    public ConfigurationRequest reopenRequest(Path set)throws IOException{return parseRequest(set.resolve("request.toml"));}
    private String request(ConfigurationRequest r){ParameterDerivationReport d=r.parameterDerivation();StringBuilder s=new StringBuilder("format_version = 5\nprimary_parameter_mode = \"").append(r.primaryParameterMode()).append("\"\nsurface_topology_assumption = \"").append(r.surfaceTopologyAssumption()).append("\"\nnode_count = ").append(r.nodeCount()).append("\nauthoritative_node_count = ").append(r.authoritativeNodeCount()==null?0:r.authoritativeNodeCount()).append("\nauthoritative_face_count = ").append(r.authoritativeFaceCount()==null?0:r.authoritativeFaceCount()).append("\nexact_degree = ").append(r.exactDegree()).append("\nintended_dimension = \"").append(r.intendedDimension()).append("\"\nexperiment_profile = \"").append(r.experimentProfile()).append("\"\nface_composition_mode = \"").append(r.faceComposition().mode()).append("\"\ncommon_face_edge_count = ").append(r.faceComposition().commonFaceEdgeCount()==null?0:r.faceComposition().commonFaceEdgeCount()).append("\nsymmetry_filter = \"").append(r.symmetryFilter()).append("\"\nmaximum_configurations = ").append(r.maximumConfigurations()).append("\nmaximum_direct_cycle_nodes = ").append(r.maximumDirectCycleNodes()).append("\nenumeration_time_millis = ").append(r.enumerationTimeLimit().toMillis()).append("\ngeneration_strategy = \"").append(persistedStrategy(r,d)).append("\"\nderived_vertex_count = ").append(d.derivedVertexCount()==null?0:d.derivedVertexCount()).append("\nderived_edge_count = ").append(d.derivedEdgeCount()==null?0:d.derivedEdgeCount()).append("\nderived_face_count = ").append(d.derivedFaceCount()==null?0:d.derivedFaceCount()).append("\narithmetic_feasible = ").append(d.arithmeticFeasible()).append("\ngeneration_strategy_available = ").append(d.generationStrategyAvailable()).append("\nderivation_reasons = \"").append(d.reasons()).append("\"\n");r.exactFaceCounts().countsByEdgeCount().forEach((m,count)->s.append("face_count_").append(m).append(" = ").append(count).append('\n'));return s.toString();}
    private static String persistedStrategy(ConfigurationRequest request,ParameterDerivationReport derivation){if(!derivation.arithmeticFeasible())return request.generationStrategy();return request.normalizedGraphRequest().selectedStrategy().name();}
    private String configuration(Configuration c,ConfigurationRequest request){var face=new TopologyEligibilityAnalyzer().analyze(c,request.experimentProfile(),request.faceComposition()).faceComposition();StringBuilder s=new StringBuilder();s.append("configuration_id = \"").append(c.id()).append("\"\nnode_count = ").append(c.nodeCount()).append("\nexact_degree = ").append(c.exactDegree()).append("\ncanonical_graph_label = \"").append(c.canonicalGraphLabel()).append("\"\nisomorphism_class_id = \"").append(c.isomorphismClassId()).append("\"\nautomorphism_group_size = ").append(c.automorphismGroupSize()).append("\ngraph_symmetry = \"").append(c.graphSymmetry()).append("\"\nconnected = true\ngeneration_index = ").append(c.generationIndex()).append("\ngeneration_method = \"").append(c.generationMethod()).append("\"\nenumeration_complete = ").append(c.enumerationComplete()).append("\nstatus = \"").append(c.status().code()).append("\"\nface_composition_mode = \"").append(face.composition().mode()).append("\"\ncommon_face_edge_count = ").append(face.composition().commonFaceEdgeCount()==null?0:face.composition().commonFaceEdgeCount()).append("\nface_composition_match = \"").append(face.match()).append("\"\nactual_face_count = ").append(face.actualFaceCount()).append("\nface_edge_count_distribution = \"").append(face.faceEdgeCountDistribution()).append("\"\nface_composition_reasons = \"").append(face.reasons()).append("\"\ncombinatorial_faces = \"").append(c.provenance().getOrDefault("combinatorialFaces","")).append("\"\nconstruction_method = \"").append(c.provenance().getOrDefault("constructionMethod","PRIMAL_GRAPH")).append("\"\nstrategy_version = \"").append(c.provenance().getOrDefault("strategyVersion","1")).append("\"\ncreated_at = \"").append(c.creationTimestamp()).append("\"\nedges = [");for(int i=0;i<c.edges().size();i++){if(i>0)s.append(", ");DiscoveryConnection e=c.edges().get(i);s.append("[").append(e.firstNodeId()).append(", ").append(e.secondNodeId()).append("]");}return s.append("]\n").toString();}
    private String summary(GenerationResult r){Metrics m=r.metrics();ParameterDerivationReport d=r.request().parameterDerivation();GenerationDiagnostics g=r.generationDiagnostics();return "set_id = \""+r.setId()+"\"\nprimary_parameter_mode = \""+r.request().primaryParameterMode()+"\"\nsurface_topology_assumption = \""+r.request().surfaceTopologyAssumption()+"\"\nderived_vertex_count = "+value(d.derivedVertexCount())+"\nderived_edge_count = "+value(d.derivedEdgeCount())+"\nderived_face_count = "+value(d.derivedFaceCount())+"\narithmetic_feasible = "+d.arithmeticFeasible()+"\ngeneration_strategy_available = "+d.generationStrategyAvailable()+"\ngeneration_strategy = \""+g.strategy()+"\"\nstrategy_version = \""+g.strategyVersion()+"\"\nconstruction_method = \""+g.constructionMethod()+"\"\nworker_count = "+g.workerCount()+"\ncompleteness = \""+g.completeness()+"\"\npartial_states_examined = "+g.partialStatesExamined()+"\npartial_states_pruned = "+g.partialStatesPruned()+"\ncompleted_candidates = "+g.completedCandidates()+"\nduplicate_candidates = "+g.duplicateCandidates()+"\npruning_counts = \""+g.pruningCounts()+"\"\nconfigurations_examined = "+m.configurationsExamined()+"\nunique_retained = "+m.uniqueConfigurationsRetained()+"\nisomorphic_duplicates_removed = "+m.isomorphicDuplicatesRemoved()+"\nsymmetric_count = "+m.symmetricCount()+"\nasymmetric_count = "+m.asymmetricCount()+"\nelapsed_milliseconds = "+m.elapsedMilliseconds()+"\nenumeration_complete = "+m.enumerationComplete()+"\nstatus = \""+r.status().code()+"\"\n";}
    private ConfigurationRequest parseRequest(Path file)throws IOException{Map<String,String> v=values(file);int version=Integer.parseInt(v.getOrDefault("format_version","3"));PrimaryParameterMode mode=version<5?PrimaryParameterMode.NODE_COUNT:PrimaryParameterMode.valueOf(unquote(v.get("primary_parameter_mode")));int normalized=Integer.parseInt(v.getOrDefault("node_count","0"));int k=Integer.parseInt(v.get("exact_degree"));Integer inputNode=mode==PrimaryParameterMode.NODE_COUNT?Integer.parseInt(v.getOrDefault("authoritative_node_count",Integer.toString(normalized))):null;Long inputFaces=mode==PrimaryParameterMode.FACE_COUNT?Long.parseLong(v.getOrDefault("authoritative_face_count","0")):null;Map<Integer,Long> counts=new TreeMap<>();v.forEach((key,value)->{if(key.startsWith("face_count_"))counts.put(Integer.parseInt(key.substring(11)),Long.parseLong(value));});ExperimentProfile profile=ExperimentProfile.valueOf(unquote(v.get("experiment_profile")));FaceCompositionMode faceMode=FaceCompositionMode.valueOf(unquote(v.getOrDefault("face_composition_mode","\"DISCOVER\"")));int common=Integer.parseInt(v.getOrDefault("common_face_edge_count","0"));FaceComposition constraint=faceMode==FaceCompositionMode.UNIFORM_FACE_SIZE?FaceComposition.uniform(common):FaceComposition.discover();return new ConfigurationRequest(normalized,k,GeometryEmbeddingDimension.valueOf(unquote(v.get("intended_dimension"))),GraphSymmetryFilter.valueOf(unquote(v.get("symmetry_filter"))),Integer.parseInt(v.get("maximum_configurations")),Duration.ofMillis(Long.parseLong(v.get("enumeration_time_millis"))),unquote(v.get("generation_strategy")),null,profile,Integer.parseInt(v.getOrDefault("maximum_direct_cycle_nodes","10000")),constraint,mode,inputNode,inputFaces,new ExactFaceCounts(counts),version<5?SurfaceTopologyAssumption.SPHERE_LIKE:SurfaceTopologyAssumption.valueOf(unquote(v.get("surface_topology_assumption"))),null);}
    private Configuration parse(Path file)throws IOException{Map<String,String> v=new HashMap<>();for(String line:Files.readAllLines(file)){int at=line.indexOf('=');if(at>0)v.put(line.substring(0,at).trim(),line.substring(at+1).trim());}int n=Integer.parseInt(v.get("node_count")),k=Integer.parseInt(v.get("exact_degree"));List<DiscoveryConnection> edges=new ArrayList<>();java.util.regex.Matcher m=java.util.regex.Pattern.compile("\\[(\\d+),\\s*(\\d+)\\]").matcher(v.get("edges"));while(m.find())edges.add(new DiscoveryConnection(Integer.parseInt(m.group(1)),Integer.parseInt(m.group(2))));var d=GeometryConfigurationDiagnostic.info(GeometryConfigurationStage.COMPLETE,GeometryConfigurationStatusCode.valueOf(unquote(v.get("status"))),"Reopened configuration","Topology-only configuration reopened from persistent storage.");Map<String,String> provenance=new TreeMap<>();String faces=unquote(v.getOrDefault("combinatorial_faces","\"\""));if(!faces.isBlank())provenance.put("combinatorialFaces",faces);provenance.put("constructionMethod",unquote(v.getOrDefault("construction_method","\"PRIMAL_GRAPH\"")));provenance.put("strategyVersion",unquote(v.getOrDefault("strategy_version","\"1\"")));return new Configuration(new ConfigurationId(unquote(v.get("configuration_id"))),n,k,edges,null,unquote(v.get("canonical_graph_label")),unquote(v.get("isomorphism_class_id")),Long.parseLong(v.get("automorphism_group_size")),GraphSymmetryClassification.valueOf(unquote(v.get("graph_symmetry"))),true,Integer.parseInt(v.get("generation_index")),unquote(v.get("generation_method")),Boolean.parseBoolean(v.get("enumeration_complete")),GeometryConfigurationStatus.of(d),List.of(d),Instant.parse(unquote(v.get("created_at"))),provenance);}
    private String unquote(String s){return s.startsWith("\"")?s.substring(1,s.length()-1):s;}
    private String csv(String s){return "\""+s.replace("\"","\"\"")+"\"";}
    private static long value(Long value){return value==null?0:value;}
    private static Map<String,String> values(Path file)throws IOException{Map<String,String> result=new HashMap<>();for(String line:Files.readAllLines(file)){int at=line.indexOf('=');if(at>0)result.put(line.substring(0,at).trim(),line.substring(at+1).trim());}return result;}
}
